#!/bin/bash
set -euo pipefail

# Prune linked SNPs using prune_graph.
#
# Input: Pairwise LD estimates generated by ngsLD.
# Pruning criteria: distance <= 50 kb and r2 >= 0.5.

PRUNE_GRAPH="path/to/prune_graph/target/release/prune_graph"
ANGSD="path/to/angsd/angsd"
RESULTS="path/to/angsd_pipeline/angsd_results/Galap24_autosome_noRelated_HWE1e-06"

PREFIX="Galap24_autosome_noRelated_HWE1e06"

LD_FILE="${RESULTS}/${PREFIX}.ld"
UNLINKED_POS="${RESULTS}/${PREFIX}_UnlinkedSites_r2_05.pos"
FORMATTED_POS="${RESULTS}/${PREFIX}_UnlinkedSites_r2_05_formatted.pos"

# Identify unlinked sites using the specified distance and LD thresholds.
"${PRUNE_GRAPH}" \
  --header \
  --in "${LD_FILE}" \
  --weight-field "r2" \
  --weight-filter "dist <= 50000 && r2 >= 0.5" \
  --out "${UNLINKED_POS}"

# Format positions for use with ANGSD.
sed 's/:/ /' "${UNLINKED_POS}" > "${FORMATTED_POS}"

# Index the formatted positions file for ANGSD.
"${ANGSD}" sites index "${FORMATTED_POS}"

# Count retained sites (assuming one header line).
awk 'END {print "Unlinked sites:", NR - 1}' "${FORMATTED_POS}"

# Use the formatted positions file with ANGSD -sites
# to restrict downstream analyses to the retained SNPs.
